contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, uint256 adjustLimit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(adjustLimit); if (__ESBMC_reverted()) return;

        uint256 limit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        bool before = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        bool reverted;
        c.wager{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool afterState = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        bool expected = (tx.origin == address(this)) && (amount == limit) && !before;

        assert(reverted == !expected || afterState);
    }

    receive() external payable {}
}

